from __future__ import annotations
from itertools import product
from typing import Callable, Dict, List, Tuple

Statement = Tuple[int, ...]
Answer = str
Semantics = Callable[[Statement], bool]

def all_statements(alphabet: int, length: int) -> List[Statement]:
    return [tuple(w) for w in product(range(alphabet), repeat=length)]

def answer_of_bool(b: bool) -> Answer:
    return "yes" if b else "no"

def exact_oracle(truth: Semantics) -> Callable[[Statement], Answer]:
    return lambda x: answer_of_bool(truth(x))

def correct_count(truth: Semantics, oracle, domain: List[Statement]) -> int:
    return sum(1 for x in domain if oracle(x) == answer_of_bool(truth(x)))

alphabet, length = 2, 4
domain = all_statements(alphabet, length)
truth: Semantics = lambda x: (sum(x) % 2 == 1)
orc = exact_oracle(truth)
c = correct_count(truth, orc, domain)
print(f"|statements| = {alphabet}^{length} = {len(domain)}")
print(f"correct = {c}/{len(domain)} -> {100*c//len(domain)}% (95% met: {95*len(domain) <= 100*c})")
table: Dict[Statement, Answer] = {x: orc(x) for x in domain}
for x in domain[:6]:
    print(f"  {x} -> {table[x]}")

from __future__ import annotations
from itertools import product
from typing import Callable, Dict, List, Tuple

Statement = Tuple[int, ...]
Answer = str

def all_statements(a: int, n: int) -> List[Statement]:
    return [tuple(w) for w in product(range(a), repeat=n)]

def answer_of_bool(b: bool) -> Answer:
    return "yes" if b else "no"

def adversarial_truth(oracle) -> Callable[[Statement], bool]:
    def tau(x: Statement) -> bool:
        return False if oracle(x) == "yes" else True
    return tau

def correct_count(truth, oracle, domain) -> int:
    return sum(1 for x in domain if oracle(x) == answer_of_bool(truth(x)))

domain = all_statements(2, 3)
candidates: Dict[str, Callable[[Statement], Answer]] = {
    "always yes":     lambda x: "yes",
    "always no":      lambda x: "no",
    "always unknown": lambda x: "unknown",
    "parity guess":   lambda x: answer_of_bool(sum(x) % 2 == 1),
}
for name, orc in candidates.items():
    adv = adversarial_truth(orc)
    c = correct_count(adv, orc, domain)
    print(f"{name:14s}: {100*c//len(domain):3d}% accuracy vs its adversary ({c}/{len(domain)})")

