function EXACT_ORACLE(alphabet a, length L, semantics tau):
    S <- all words of length L over {0,...,a-1}      # |S| = a^L
    table <- empty map
    for each x in S:
        if tau(x) = true:
            table[x] <- "yes"
        else:
            table[x] <- "no"
    return table            # correct on all |S| statements: 100% accuracy

