from __future__ import annotations
from typing import Callable, List

def diagonal_jump(row: Callable[[int, int], bool], k_max: int) -> List[bool]:
    return [not row(k, k) for k in range(k_max)]

def escapes_all_rows(row: Callable[[int, int], bool], k_max: int) -> bool:
    j = diagonal_jump(row, k_max)
    return all(j[k] != row(k, k) for k in range(k_max))
